SELECT id, task_no, biz_type, operator_id, operator_name, filter_json,
       row_count, file_size, file_path, status, error_msg,
       started_at, finished_at, created_at
  FROM export_tasks
 WHERE operator_id = #{operatorId}

   AND status = #{status}

 ORDER BY id DESC
 LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM export_tasks
WHERE operator_id = #{operatorId}

   AND status = #{status}
